import {
  darkSelector,
  declarationsUnder,
  lightSelector,
  reducedMotionSelector,
} from "./buildTokens.ts";
import { parseCssScopes } from "./parseCss.ts";

import type { TokenSourceTexts } from "./buildTokens.ts";

const header = [
  "/* Ki-Lo design tokens as CSS custom properties, with the design system's own names. */",
  "/* Generated by scripts/generate.ts from src/source/. Do not edit by hand. */",
  '/* Dark is the default on :root. Light overrides it under [data-theme="light"]. */',
].join("\n");

const rule = (selector: string, declarations: Record<string, string>, indent = ""): string => {
  const lines = Object.entries(declarations).map(
    ([property, value]) => `${indent}  ${property}: ${value};`,
  );
  return `${indent}${selector} {\n${lines.join("\n")}\n${indent}}`;
};

/**
 * The tokens as one stylesheet, for anything that reads plain CSS variables (`var(--surface)`)
 * rather than the Tailwind preset. Built from the design system's own CSS, so each name and value
 * is the design's. The `kl-*` keyframes are not tokens and are left out.
 */
export const buildTokenCss = (sources: TokenSourceTexts): string => {
  const stylesheets = [
    sources.colorsCss,
    sources.spacingCss,
    sources.typographyCss,
    sources.motionCss,
    sources.trainingCss,
  ].map(parseCssScopes);

  const reducedMotion = rule(":root", declarationsUnder(stylesheets, reducedMotionSelector), "  ");

  return `${[
    header,
    rule(darkSelector, declarationsUnder(stylesheets, darkSelector)),
    rule(lightSelector, declarationsUnder(stylesheets, lightSelector)),
    `@media (prefers-reduced-motion: reduce) {\n${reducedMotion}\n}`,
  ].join("\n\n")}\n`;
};
